int send_smb_request(struct TCP_Server_Info *server, struct smb_rqst *rqst) {
    int result = 0;
    int total_bytes_sent = 0;
    int expected_length = 0;

    if (!server || !rqst) {
        return -EINVAL;
    }

    if (rqst->rq_nvec <= 0) {
        return -EINVAL;
    }

    for (int i = 0; i < rqst->rq_nvec; i++) {
        expected_length += rqst->rq_iov[i].iov_len;
    }

    result = setsockopt(server->sock, IPPROTO_TCP, TCP_CORK, &(int){1}, sizeof(int));
    if (result < 0) {
        return result;
    }

    total_bytes_sent = smb_send_kvec(server, rqst->rq_iov, 0);
    if (total_bytes_sent < 0) {
        result = total_bytes_sent;
        goto uncork;
    }

    for (int i = 1; i < rqst->rq_nvec; i++) {
        int bytes_sent = smb_send_kvec(server, &rqst->rq_iov[i], 0);
        if (bytes_sent < 0) {
            result = bytes_sent;
            goto uncork;
        }
        total_bytes_sent += bytes_sent;
    }

uncork:
    result = setsockopt(server->sock, IPPROTO_TCP, TCP_CORK, &(int){0}, sizeof(int));
    if (result < 0) {
        return result;
    }

    if (total_bytes_sent != expected_length) {
        server->tcp_status = TCP_STATUS_NEED_RECONNECT;
        return -EIO;
    }

    return 0;
}
